def interval_intersection(lA, uA, lB, uB):
    if (lB >= lA and lB <= uA):
        if uB < uA:
            return uB - lB
        else:
            return uA - lB
    elif (lA >= lB and lA <= uB):
        if uA < uB:
            return uA - lA
        else:
            return uB - lA
    return 0
